// Turn any Telegram update into one routed item: command, args, and the file to download (if any).
const update = $input.first().json;
const msg = update.message || {};
const text = String(msg.text || msg.caption || '').trim();
const firstToken = text.split(/\s+/)[0] || '';
const command = firstToken.startsWith('/') ? firstToken.split('@')[0].toLowerCase() : '';
const args = command ? text.slice(firstToken.length).trim() : text;

const photos = Array.isArray(msg.photo) ? msg.photo : [];
const doc = msg.document || null;
const docName = doc ? String(doc.file_name || '') : '';
const docMime = doc ? String(doc.mime_type || '') : '';
const isImageDoc = !!doc && docMime.startsWith('image/');
const isCsvDoc = !!doc && !isImageDoc && (/\.(csv|txt)$/i.test(docName) || /csv|comma-separated/i.test(docMime));

// Telegram lists photo sizes smallest first.
let fileId = '';
if (photos.length) fileId = photos[photos.length - 1].file_id;
else if (doc) fileId = doc.file_id;

const COMMAND_ROUTES = {
  '/start': 'help',
  '/help': 'help',
  '/wallet': 'set_wallet',
  '/sync': 'sync',
  '/market': 'market',
  '/news': 'news',
  '/analyze': 'analyze',
  '/analyse': 'analyze',
  '/risk': 'risk',
};

let route;
if (photos.length || isImageDoc) route = 'chart';
else if (isCsvDoc) route = 'import';
else if (doc) route = 'help';
else if (command === '/portfolio' || command === '/holdings') route = args ? 'save_holdings' : 'view_portfolio';
else if (command) route = COMMAND_ROUTES[command] || 'help';
else route = text ? 'ask' : 'help';

return [{
  json: {
    chat_id: msg.chat ? msg.chat.id : null,
    telegram_id: msg.from ? msg.from.id : (msg.chat ? msg.chat.id : null),
    username: msg.from ? (msg.from.username || msg.from.first_name || '') : '',
    text,
    command,
    args,
    route,
    file_id: fileId,
    file_name: docName,
  },
}];

// Combine the message with the analyst skills and the user's holdings, plus reference data
// that the downstream nodes share (symbol classification and Yahoo Finance ticker mapping).
const base = $('Normalize Message').first().json;

const skills = {};
for (const it of $('Load Skills').all()) {
  const s = it.json || {};
  if (s.slug && s.body && s.enabled !== false) skills[s.slug] = s.body;
}

const holdings = $input.all().map((i) => i.json).filter((h) => h && h.symbol);

const ref = {
  crypto: ['BTC', 'ETH', 'SOL', 'BNB', 'XRP', 'ADA', 'DOGE', 'AVAX', 'DOT', 'LINK', 'MATIC', 'POL', 'LTC', 'BCH',
    'ATOM', 'UNI', 'AAVE', 'ARB', 'OP', 'SUI', 'APT', 'SEI', 'TIA', 'INJ', 'NEAR', 'TON', 'TRX', 'XLM', 'HYPE',
    'PEPE', 'KPEPE', 'WIF', 'BONK', 'SHIB', 'FET', 'RNDR', 'RENDER', 'TAO', 'ENA', 'JUP', 'PYTH', 'ONDO', 'LDO',
    'MKR', 'CRV', 'FIL', 'ICP', 'ETC', 'HBAR', 'ALGO', 'VET', 'XMR', 'KAS', 'STX', 'IMX', 'GALA', 'SAND', 'MANA',
    'USDT', 'USDC'],
  cryptoNames: {
    BTC: 'Bitcoin', ETH: 'Ethereum', SOL: 'Solana', BNB: 'BNB', XRP: 'XRP', ADA: 'Cardano', DOGE: 'Dogecoin',
    AVAX: 'Avalanche', DOT: 'Polkadot', LINK: 'Chainlink', LTC: 'Litecoin', ARB: 'Arbitrum', OP: 'Optimism',
    SUI: 'Sui', HYPE: 'Hyperliquid', TON: 'Toncoin', NEAR: 'NEAR Protocol', TAO: 'Bittensor', ENA: 'Ethena',
  },
  // Google Finance / common exchange codes -> Yahoo Finance suffix and trading currency.
  exchanges: {
    NASDAQ: ['', 'USD'], NYSE: ['', 'USD'], NYSEARCA: ['', 'USD'], NYSEAMERICAN: ['', 'USD'], BATS: ['', 'USD'],
    OTCMKTS: ['', 'USD'], JSE: ['.JO', 'ZAR'], LON: ['.L', 'GBP'], LSE: ['.L', 'GBP'], TSE: ['.T', 'JPY'],
    TYO: ['.T', 'JPY'], HKG: ['.HK', 'HKD'], ASX: ['.AX', 'AUD'], TSX: ['.TO', 'CAD'], TSXV: ['.V', 'CAD'],
    FRA: ['.F', 'EUR'], ETR: ['.DE', 'EUR'], XETRA: ['.DE', 'EUR'], EPA: ['.PA', 'EUR'], AMS: ['.AS', 'EUR'],
    BIT: ['.MI', 'EUR'], BME: ['.MC', 'EUR'], SWX: ['.SW', 'CHF'], VTX: ['.SW', 'CHF'], NSE: ['.NS', 'INR'],
    BOM: ['.BO', 'INR'], STO: ['.ST', 'SEK'], CPH: ['.CO', 'DKK'], OSL: ['.OL', 'NOK'], KRX: ['.KS', 'KRW'],
    TPE: ['.TW', 'TWD'], SGX: ['.SI', 'SGD'], NZE: ['.NZ', 'NZD'], BVMF: ['.SA', 'BRL'],
  },
  suffixCurrency: {
    '.JO': 'ZAR', '.L': 'GBP', '.T': 'JPY', '.HK': 'HKD', '.AX': 'AUD', '.TO': 'CAD', '.V': 'CAD', '.F': 'EUR',
    '.DE': 'EUR', '.PA': 'EUR', '.AS': 'EUR', '.MI': 'EUR', '.MC': 'EUR', '.SW': 'CHF', '.NS': 'INR', '.BO': 'INR',
    '.ST': 'SEK', '.CO': 'DKK', '.OL': 'NOK', '.KS': 'KRW', '.TW': 'TWD', '.SI': 'SGD', '.NZ': 'NZD', '.SA': 'BRL',
  },
  commodities: { GOLD: 'GC=F', SILVER: 'SI=F', OIL: 'CL=F', WTI: 'CL=F', BRENT: 'BZ=F', NATGAS: 'NG=F', COPPER: 'HG=F' },
};

return [{ json: { ...base, skills, holdings, ref } }];

// Parse "/portfolio NASDAQ:AAPL:10@182.5, NPN.JO:3@2900, BTC:0.25" into holdings rows.
const ctx = $input.first().json;
const ref = ctx.ref;
const crypto = new Set(ref.crypto);

const rows = [];
const invalid = [];
for (const raw of String(ctx.args || '').split(/[,;\n]+/)) {
  const part = raw.trim();
  if (!part) continue;
  const m = part.match(/^([A-Za-z0-9.:=^\-]+?)\s*[:\s]\s*(-?\d+(?:\.\d+)?)\s*(?:@\s*(\d+(?:\.\d+)?))?$/);
  if (!m) {
    invalid.push(part);
    continue;
  }
  let symbol = m[1].toUpperCase();
  let exchange = null;
  const colon = symbol.lastIndexOf(':');
  if (colon > 0) {
    exchange = symbol.slice(0, colon);
    symbol = symbol.slice(colon + 1);
  }
  const suffix = (symbol.match(/\.[A-Z]+$/) || [''])[0];
  let currency = 'USD';
  if (exchange && ref.exchanges[exchange]) currency = ref.exchanges[exchange][1];
  else if (ref.suffixCurrency[suffix]) currency = ref.suffixCurrency[suffix];

  let assetClass = 'stock';
  if (crypto.has(symbol)) assetClass = 'crypto';
  else if (ref.commodities[symbol] || /=F$/.test(symbol)) assetClass = 'commodity';

  rows.push({
    symbol,
    exchange,
    quantity: Number(m[2]),
    avg_cost: m[3] ? Number(m[3]) : null,
    currency: assetClass === 'crypto' ? 'USD' : currency,
    asset_class: assetClass,
  });
}

return [{
  json: {
    chat_id: ctx.chat_id,
    rows,
    invalid,
    body: {
      p_telegram_id: ctx.telegram_id,
      p_username: ctx.username,
      p_source: 'manual',
      p_rows: rows,
      p_replace: false,
    },
  },
}];

const parsed = $('Parse Holdings Command').first().json;
const res = $input.first().json;

let reply;
if (!parsed.rows.length) {
  reply = '⚠️ Nothing saved. Format:\n/portfolio NASDAQ:AAPL:10@182.5, NPN.JO:3@2900, BTC:0.25\n(SYMBOL:QUANTITY@AVERAGE_COST, cost optional)';
} else if (res.message || res.error) {
  reply = '❌ Could not save holdings: ' + (res.message || JSON.stringify(res.error));
} else {
  const list = parsed.rows
    .map((r) => '• ' + (r.exchange ? r.exchange + ':' : '') + r.symbol + ' ' + r.quantity + (r.avg_cost != null ? ' @ ' + r.avg_cost + ' ' + r.currency : ''))
    .join('\n');
  reply = '✅ Saved ' + parsed.rows.length + ' holding(s):\n' + list + '\n\nView them with /portfolio or get a review with /analyze.';
}
if (parsed.invalid.length) reply += '\n\n⚠️ Skipped (could not read): ' + parsed.invalid.join(', ');

return [{ json: { chat_id: parsed.chat_id, reply } }];

const ctx = $input.first().json;
const rows = ctx.holdings || [];

const fmt = (n, dp) => {
  const v = Number(n);
  if (!isFinite(v)) return '-';
  return v.toLocaleString('en-US', { maximumFractionDigits: dp === undefined ? 4 : dp });
};

let reply;
if (!rows.length) {
  reply = '📊 No holdings stored yet.\n\n'
    + 'Add Google Finance holdings:\n/portfolio NASDAQ:AAPL:10@182.5, NPN.JO:3@2900\n'
    + 'or send your holdings as a CSV with the caption /import google\n\n'
    + 'Link Invo: /wallet 0xYourAddress then /sync';
} else {
  const LABELS = { google_finance: 'Google Finance', invo: 'Invo / Hyperliquid', binance: 'Binance', manual: 'Manual' };
  const bySource = {};
  for (const r of rows) (bySource[r.source] = bySource[r.source] || []).push(r);
  const sections = [];
  for (const [source, list] of Object.entries(bySource)) {
    const lines = list.map((r) => {
      if (r.asset_class === 'cash') return '• ' + r.symbol + ' equity ' + fmt(r.quantity, 2);
      if (r.asset_class === 'crypto_perp') {
        const side = Number(r.quantity) < 0 ? 'SHORT' : 'LONG';
        return '• ' + r.symbol + '-PERP ' + side + ' ' + fmt(Math.abs(r.quantity)) + ' @ ' + fmt(r.avg_cost, 2)
          + (r.leverage ? ' | ' + fmt(r.leverage, 1) + 'x' : '')
          + (r.unrealized_pnl != null ? ' | uPnL ' + fmt(r.unrealized_pnl, 2) : '')
          + (r.liquidation_price ? ' | liq ' + fmt(r.liquidation_price, 2) : '');
      }
      return '• ' + (r.exchange ? r.exchange + ':' : '') + r.symbol + ' ' + fmt(r.quantity)
        + (r.avg_cost != null ? ' @ ' + fmt(r.avg_cost, 2) + ' ' + r.currency : '');
    });
    sections.push((LABELS[source] || source) + '\n' + lines.join('\n'));
  }
  const lastUpdate = rows.map((r) => r.updated_at).sort().pop();
  reply = '📊 Your holdings (' + rows.length + ')\n\n' + sections.join('\n\n')
    + '\n\nLast updated ' + String(lastUpdate || '').slice(0, 16).replace('T', ' ') + ' UTC'
    + '\n💡 /analyze for the investor panel, /risk for metrics';
}

return [{ json: { chat_id: ctx.chat_id, reply } }];

// Map an uploaded CSV to holdings (Google Finance style) or trade history (Hyperliquid/Invo, Binance, generic).
// Caption hints: "/import google", "/import invo", "/import binance".
const ctx = $('Build Context').first().json;
const ref = ctx.ref;
const crypto = new Set(ref.crypto);
const records = $input.all().map((i) => i.json).filter((r) => r && Object.keys(r).length);
const hint = String(ctx.args || ctx.text || '').toLowerCase();

const norm = (k) => String(k).toLowerCase().replace(/[^a-z0-9]/g, '');
const pick = (rec, names) => {
  for (const [k, v] of Object.entries(rec)) {
    if (names.includes(norm(k)) && v !== '' && v !== null && v !== undefined) return v;
  }
  return null;
};
const num = (v) => {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return v;
  const m = String(v).replace(/,/g, '').match(/-?\d+(?:\.\d+)?(?:e-?\d+)?/i);
  return m ? Number(m[0]) : null;
};
const parseTime = (v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number' || /^\d{10,13}$/.test(String(v))) {
    const n = Number(v);
    return new Date(n < 1e12 ? n * 1000 : n).toISOString();
  }
  const s = String(v).trim();
  const direct = Date.parse(s.replace(' - ', ' '));
  if (!isNaN(direct)) return new Date(direct).toISOString();
  // dd/mm/yyyy or mm/dd/yyyy with optional time
  const m = s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})(?:\D+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
  if (m) {
    let a = Number(m[1]);
    let b = Number(m[2]);
    const month = a > 12 ? b : a;
    const day = a > 12 ? a : b;
    const d = Date.UTC(Number(m[3]), month - 1, day, Number(m[4] || 0), Number(m[5] || 0), Number(m[6] || 0));
    return new Date(d).toISOString();
  }
  return null;
};
const cleanSymbol = (s) => {
  let sym = String(s || '').trim().toUpperCase();
  sym = sym.split('/')[0].replace(/-PERP$/, '').replace(/^\$/, '');
  if (!sym.includes(':') && /^[A-Z0-9]+(USDT|USDC|BUSD|FDUSD|TUSD)$/.test(sym)) sym = sym.replace(/(USDT|USDC|BUSD|FDUSD|TUSD)$/, '');
  return sym;
};
const sideOf = (rawSide, rawDir) => {
  const s = String(rawDir || rawSide || '').toLowerCase();
  if (!s) return null;
  if (s.includes('short > long') || s.includes('close short') || s.includes('open long')) return 'buy';
  if (s.includes('long > short') || s.includes('close long') || s.includes('open short')) return 'sell';
  if (/^(b|buy|bid|long)/.test(s)) return 'buy';
  if (/^(a|s|sell|ask|short)/.test(s)) return 'sell';
  return null;
};

const COLS = {
  symbol: ['symbol', 'ticker', 'coin', 'asset', 'instrument', 'pair', 'security', 'stock', 'market'],
  quantity: ['quantity', 'qty', 'shares', 'units', 'amount', 'size', 'sz', 'executed', 'filled', 'position', 'holdings'],
  price: ['price', 'px', 'executionprice', 'fillprice', 'tradeprice', 'avgprice', 'averageprice'],
  avgCost: ['averagecost', 'avgcost', 'averageprice', 'avgprice', 'costpershare', 'costbasispershare', 'purchaseprice', 'buyprice', 'entryprice', 'price'],
  exchange: ['exchange', 'exchangename', 'listing'],
  currency: ['currency', 'ccy'],
  time: ['time', 'date', 'datetime', 'dateutc', 'timestamp', 'executedat', 'tradedate', 'filledtime', 'tradetime', 'createdat'],
  side: ['side', 'type', 'action', 'buysell', 'tradetype'],
  dir: ['dir', 'direction'],
  fee: ['fee', 'fees', 'commission'],
  feeCurrency: ['feecoin', 'feecurrency', 'feeasset', 'feetoken'],
  pnl: ['closedpnl', 'realizedpnl', 'realisedpnl', 'pnl', 'profit'],
  id: ['tradeid', 'tid', 'id', 'fillid', 'transactionid', 'hash'],
};

const header = records.length ? Object.keys(records[0]).map(norm) : [];
const has = (names) => header.some((h) => names.includes(h));
const kind = has(COLS.time) && (has(COLS.side) || has(COLS.dir)) && has(COLS.price) ? 'trades' : 'holdings';

let source;
if (hint.includes('invo') || hint.includes('hyper')) source = 'invo';
else if (hint.includes('binance')) source = 'binance';
else if (hint.includes('google')) source = 'google_finance';
else source = kind === 'trades' ? 'csv' : 'google_finance';

const rows = [];
const skipped = [];
records.forEach((rec, idx) => {
  const symRaw = pick(rec, COLS.symbol);
  if (!symRaw) return skipped.push(idx + 2);
  if (kind === 'trades') {
    const symbol = cleanSymbol(symRaw);
    const side = sideOf(pick(rec, COLS.side), pick(rec, COLS.dir));
    const quantity = Math.abs(num(pick(rec, COLS.quantity)) || 0);
    const price = num(pick(rec, COLS.price));
    const executedAt = parseTime(pick(rec, COLS.time));
    if (!symbol || !side || !quantity || price === null || !executedAt) return skipped.push(idx + 2);
    const explicitId = pick(rec, COLS.id);
    rows.push({
      external_id: explicitId ? String(explicitId) : ['csv', symbol, side, quantity, price, executedAt].join('|'),
      symbol,
      side,
      direction: pick(rec, COLS.dir) || null,
      quantity,
      price,
      fee: num(pick(rec, COLS.fee)) || 0,
      fee_currency: pick(rec, COLS.feeCurrency),
      realized_pnl: num(pick(rec, COLS.pnl)),
      executed_at: executedAt,
      raw: rec,
    });
  } else {
    let symbol = String(symRaw).trim().toUpperCase();
    let exchange = pick(rec, COLS.exchange);
    const colon = symbol.lastIndexOf(':');
    if (colon > 0) {
      exchange = exchange || symbol.slice(0, colon);
      symbol = symbol.slice(colon + 1);
    }
    exchange = exchange ? String(exchange).toUpperCase() : null;
    const quantity = num(pick(rec, COLS.quantity));
    if (!symbol || quantity === null) return skipped.push(idx + 2);
    const suffix = (symbol.match(/\.[A-Z]+$/) || [''])[0];
    const isCrypto = crypto.has(cleanSymbol(symbol)) || source === 'invo' || source === 'binance';
    if (isCrypto) symbol = cleanSymbol(symbol);
    const currency = pick(rec, COLS.currency)
      || (exchange && ref.exchanges[exchange] ? ref.exchanges[exchange][1] : null)
      || ref.suffixCurrency[suffix]
      || 'USD';
    rows.push({
      symbol,
      exchange,
      quantity,
      avg_cost: num(pick(rec, COLS.avgCost)),
      currency: String(currency).toUpperCase(),
      asset_class: isCrypto ? 'crypto' : (ref.commodities[symbol] || /=F$/.test(symbol) ? 'commodity' : 'stock'),
    });
  }
});

const rpc = kind === 'trades' ? 'ingest_trades' : 'upsert_holdings';
const body = kind === 'trades'
  ? { p_telegram_id: ctx.telegram_id, p_username: ctx.username, p_source: source, p_rows: rows }
  : { p_telegram_id: ctx.telegram_id, p_username: ctx.username, p_source: source, p_rows: rows, p_replace: rows.length > 0 };

return [{
  json: {
    chat_id: ctx.chat_id,
    kind,
    source,
    rpc,
    body,
    valid: rows.length,
    skipped,
    columns: records.length ? Object.keys(records[0]) : [],
    file_name: ctx.file_name,
  },
}];

const plan = $('Map Import Rows').first().json;
const res = $input.first().json;
const LABELS = { google_finance: 'Google Finance', invo: 'Invo / Hyperliquid', binance: 'Binance', csv: 'CSV', manual: 'Manual' };

let reply;
if (!plan.valid) {
  reply = '⚠️ No usable rows found in ' + (plan.file_name || 'the file') + '.\n'
    + 'Columns seen: ' + (plan.columns.join(', ') || 'none') + '\n\n'
    + 'Holdings CSV needs: Symbol, Quantity (optional: Average cost, Exchange, Currency).\n'
    + 'Trades CSV needs: Time/Date, Symbol/Coin, Side/Dir, Price/Px, Quantity/Size.';
} else if (res.message || res.error) {
  reply = '❌ Import failed: ' + (res.message || JSON.stringify(res.error));
} else if (plan.kind === 'trades') {
  reply = '✅ Imported ' + (res.inserted ?? 0) + ' new trade(s) from ' + plan.valid + ' row(s) as ' + (LABELS[plan.source] || plan.source)
    + ' (duplicates are skipped automatically).';
} else {
  reply = '✅ Replaced your ' + (LABELS[plan.source] || plan.source) + ' holdings with ' + (res.upserted ?? plan.valid) + ' position(s)'
    + (res.deleted ? ' and removed ' + res.deleted + ' that are no longer in the file' : '') + '.\nSee them with /portfolio.';
}
if (plan.valid && plan.skipped.length) reply += '\n⚠️ Skipped CSV line(s): ' + plan.skipped.slice(0, 20).join(', ') + (plan.skipped.length > 20 ? ' …' : '');

return [{ json: { chat_id: plan.chat_id, reply } }];

const ctx = $('Build Context').first().json;
const res = $input.first().json;

let reply;
if (res.wallet) {
  reply = '✅ Linked Hyperliquid wallet ' + res.wallet.slice(0, 6) + '…' + res.wallet.slice(-4)
    + '.\nSend /sync to import your Invo trade history and open positions.';
} else {
  reply = '❌ ' + (res.message || 'Could not save the wallet.')
    + '\n\nUse your PUBLIC address only, e.g. /wallet 0x1234…abcd (Invo → Wallet → copy address). Never send a private key or seed phrase.';
}

return [{ json: { chat_id: ctx.chat_id, reply } }];

// Map Hyperliquid fills (what Invo executed) to trade rows, and the clearinghouse state to holdings.
const ctx = $('Build Context').first().json;
const wallet = $('Load Sync State').first().json.hyperliquid_wallet;

const parse = (v) => {
  if (v === null || v === undefined) return null;
  if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (e) { return null; }
};

const fillsRaw = $('Fetch Hyperliquid Fills').first().json;
const fills = parse(fillsRaw.data);
const fillsOk = Array.isArray(fills);

const stateRaw = $('Fetch Hyperliquid Positions').first().json;
const state = parse(stateRaw.data !== undefined ? stateRaw.data : stateRaw);
const stateOk = !!state && Array.isArray(state.assetPositions);

const trades = (fillsOk ? fills : []).map((f) => ({
  external_id: String(f.tid !== undefined ? f.tid : f.hash + ':' + f.time),
  symbol: String(f.coin || '').toUpperCase(),
  side: f.side === 'B' ? 'buy' : 'sell',
  direction: f.dir || null,
  quantity: Number(f.sz),
  price: Number(f.px),
  fee: Number(f.fee || 0),
  fee_currency: f.feeToken || 'USDC',
  realized_pnl: f.closedPnl !== undefined ? Number(f.closedPnl) : null,
  executed_at: new Date(Number(f.time)).toISOString(),
  raw: f,
}));

const positions = [];
let accountValue = null;
if (stateOk) {
  for (const ap of state.assetPositions) {
    const p = ap.position || {};
    if (!p.coin || Number(p.szi) === 0) continue;
    positions.push({
      symbol: String(p.coin).toUpperCase(),
      asset_class: 'crypto_perp',
      quantity: Number(p.szi),
      avg_cost: p.entryPx !== undefined ? Number(p.entryPx) : null,
      currency: 'USD',
      leverage: p.leverage && p.leverage.value !== undefined ? Number(p.leverage.value) : null,
      liquidation_price: p.liquidationPx ? Number(p.liquidationPx) : null,
      unrealized_pnl: p.unrealizedPnl !== undefined ? Number(p.unrealizedPnl) : null,
    });
  }
  accountValue = state.marginSummary ? Number(state.marginSummary.accountValue) : null;
  if (accountValue !== null && isFinite(accountValue)) {
    positions.push({ symbol: 'USDC', asset_class: 'cash', quantity: accountValue, avg_cost: 1, currency: 'USD' });
  }
}

const realized = trades.reduce((s, t) => s + (t.realized_pnl || 0), 0);
const fees = trades.reduce((s, t) => s + (t.fee || 0), 0);

return [{
  json: {
    chat_id: ctx.chat_id,
    wallet,
    fills_ok: fillsOk,
    state_ok: stateOk,
    fills_error: fillsOk ? null : String(fillsRaw.data || fillsRaw.error && fillsRaw.error.message || 'no response').slice(0, 200),
    fill_count: trades.length,
    more_available: trades.length >= 2000,
    position_count: positions.filter((p) => p.asset_class === 'crypto_perp').length,
    account_value: accountValue,
    realized_in_batch: realized,
    fees_in_batch: fees,
    positions,
    trades_body: { p_telegram_id: ctx.telegram_id, p_username: ctx.username, p_source: 'invo', p_rows: trades },
    // Only replace stored positions when Hyperliquid answered; otherwise leave them untouched.
    positions_body: { p_telegram_id: ctx.telegram_id, p_username: ctx.username, p_source: 'invo', p_rows: stateOk ? positions : [], p_replace: stateOk },
  },
}];

const m = $('Map Hyperliquid Data').first().json;
const saved = $('Save Hyperliquid Fills').first().json;
