const body = (name) => {
  try {
    const j = $(name).first().json;
    const v = j.data !== undefined ? j.data : j;
    return typeof v === 'string' ? JSON.parse(v) : v;
  } catch (e) {
    return null;
  }
};
const round = (v, dp) => (v === null || v === undefined || !isFinite(v) ? null : Number(Number(v).toFixed(dp === undefined ? 2 : dp)));
const pct = (a, b) => (a && b ? (a / b - 1) * 100 : null);

const sma = (xs, n) => (xs.length >= n ? xs.slice(-n).reduce((s, x) => s + x, 0) / n : null);
const rsi = (xs, n) => {
  if (xs.length <= n) return null;
  let gain = 0;
  let loss = 0;
  for (let i = 1; i <= n; i++) {
    const d = xs[i] - xs[i - 1];
    if (d >= 0) gain += d; else loss -= d;
  }
  gain /= n;
  loss /= n;
  for (let i = n + 1; i < xs.length; i++) {
    const d = xs[i] - xs[i - 1];
    gain = (gain * (n - 1) + Math.max(d, 0)) / n;
    loss = (loss * (n - 1) + Math.max(-d, 0)) / n;
  }
  return loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);
};
const atr = (c, n) => {
  if (c.length <= n) return null;
  const trs = [];
  for (let i = 1; i < c.length; i++) {
    trs.push(Math.max(c[i].h - c[i].l, Math.abs(c[i].h - c[i - 1].c), Math.abs(c[i].l - c[i - 1].c)));
  }
  let a = trs.slice(0, n).reduce((s, x) => s + x, 0) / n;
  for (let i = n; i < trs.length; i++) a = (a * (n - 1) + trs[i]) / n;
  return a;
};

const fromBinance = (raw) => (Array.isArray(raw) ? raw.map((k) => ({ t: Number(k[0]), o: Number(k[1]), h: Number(k[2]), l: Number(k[3]), c: Number(k[4]), v: Number(k[5]) })) : []);
const fromYahoo = (raw) => {
  const r = raw && raw.chart && raw.chart.result && raw.chart.result[0];
  if (!r || !r.timestamp) return { candles: [], currency: null };
  const q = r.indicators.quote[0];
  const candles = [];
  r.timestamp.forEach((t, i) => {
    if (q.close[i] === null || q.close[i] === undefined) return;
    candles.push({ t: t * 1000, o: q.open[i], h: q.high[i], l: q.low[i], c: q.close[i], v: q.volume ? q.volume[i] : null });
  });
  return { candles, currency: r.meta && r.meta.currency };
};

const indicators = (candles, label, periodsPerYear) => {
  if (candles.length < 20) return null;
  const closes = candles.map((k) => k.c);
  const last = closes[closes.length - 1];
  const back = (n) => (closes.length > n ? closes[closes.length - 1 - n] : null);
  const s20 = sma(closes, 20);
  const s50 = sma(closes, 50);
  const s200 = sma(closes, 200);
  const s50prev = closes.length >= 55 ? sma(closes.slice(0, -5), 50) : null;
  const s200prev = closes.length >= 205 ? sma(closes.slice(0, -5), 200) : null;
  const window = closes.slice(-Math.min(closes.length, periodsPerYear));
  const hi = Math.max(...window);
  const lo = Math.min(...window);
  const vols = candles.slice(-21, -1).map((k) => k.v).filter((v) => v);
  const avgVol = vols.length ? vols.reduce((s, v) => s + v, 0) / vols.length : null;
  const lastCompleteVol = candles.length > 1 ? candles[candles.length - 2].v : null;
  const a = atr(candles, 14);
  return {
    timeframe: label,
    bars: candles.length,
    last_close: round(last, 6),
    sma20: round(s20, 6),
    sma50: round(s50, 6),
    sma200: round(s200, 6),
    price_vs_sma50_pct: round(pct(last, s50)),
    price_vs_sma200_pct: round(pct(last, s200)),
    sma50_slope_5bars_pct: round(pct(s50, s50prev), 3),
    sma200_slope_5bars_pct: round(pct(s200, s200prev), 3),
    golden_cross: s50 && s200 ? s50 > s200 : null,
    rsi14: round(rsi(closes, 14), 1),
    rsi14_5bars_ago: round(rsi(closes.slice(0, -5), 14), 1),
    atr14_pct: round(a ? (a / last) * 100 : null),
    return_1bar_pct: round(pct(last, back(1))),
    return_7bars_pct: round(pct(last, back(7))),
    return_30bars_pct: round(pct(last, back(30))),
    return_90bars_pct: round(pct(last, back(90))),
    range_high: round(hi, 6),
    range_low: round(lo, 6),
    from_range_high_pct: round(pct(last, hi)),
    from_range_low_pct: round(pct(last, lo)),
    last_complete_volume_vs_20avg: round(avgVol && lastCompleteVol ? lastCompleteVol / avgVol : null),
  };
};

