// Merge the feeds, drop duplicates and stale items, rank by relevance to the holdings, build the prompt.
const ctx = $('Build Context').first().json;
const q = $('News Query').first().json;

const read = (name, fallbackSource) => {
  try {
    return $(name).all().map((i) => i.json).filter((j) => j && j.title).map((j) => ({ ...j, feed: fallbackSource }));
  } catch (e) {
    return [];
  }
};
const items = [
  ...read('Google News Search', 'Google News'),
  ...read('CoinDesk Headlines', 'CoinDesk'),
  ...read('CNBC Markets Headlines', 'CNBC'),
];

const now = Date.now();
const seen = new Set();
const ranked = [];
for (const it of items) {
  let title = String(it.title).trim();
  let source = it.feed;
  // Google News titles end with " - Publisher".
  const dash = title.lastIndexOf(' - ');
  if (it.feed === 'Google News' && dash > 20) {
    source = title.slice(dash + 3);
    title = title.slice(0, dash);
  }
  const key = title.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 80);
  if (seen.has(key)) continue;
  seen.add(key);
  const ts = Date.parse(it.isoDate || it.pubDate || '');
  const ageH = isNaN(ts) ? 48 : (now - ts) / 36e5;
  if (ageH > 72) continue;
  const text = (title + ' ' + (it.contentSnippet || '')).toLowerCase();
  const hits = q.keywords.filter((k) => text.includes(k)).length;
  const score = hits * 3 + (it.feed === 'Google News' ? 2 : 0) - ageH / 12;
  ranked.push({
    source,
    title,
    published_utc: isNaN(ts) ? 'unknown' : new Date(ts).toISOString().slice(0, 16).replace('T', ' '),
    snippet: String(it.contentSnippet || '').replace(/\s+/g, ' ').slice(0, 220),
    score,
  });
}
ranked.sort((a, b) => b.score - a.score);
const top = ranked.slice(0, 15);

