// Value every holding in USD, then compute exposure, concentration, historical-simulation VaR,
// beta, risk contribution, correlations, perp leverage/liquidation distance and trade statistics.
const ctx = $('Build Context').first().json;
const plan = $('Plan Price Requests').all().map((i) => i.json);
const responses = $('Fetch Price History').all().map((i) => i.json);

const parse = (v) => {
  if (v === null || v === undefined) return null;
  if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (e) { return null; }
};
const round = (v, dp) => (v === null || v === undefined || !isFinite(v) ? null : Number(Number(v).toFixed(dp === undefined ? 2 : dp)));
const mean = (xs) => (xs.length ? xs.reduce((s, x) => s + x, 0) / xs.length : 0);
const sd = (xs) => {
  if (xs.length < 2) return 0;
  const m = mean(xs);
  return Math.sqrt(xs.reduce((s, x) => s + (x - m) * (x - m), 0) / (xs.length - 1));
};
const cov = (a, b) => {
  const n = Math.min(a.length, b.length);
  if (n < 2) return 0;
  const ma = mean(a.slice(0, n));
  const mb = mean(b.slice(0, n));
  let s = 0;
  for (let i = 0; i < n; i++) s += (a[i] - ma) * (b[i] - mb);
  return s / (n - 1);
};
const corr = (a, b) => {
  const d = sd(a) * sd(b);
  return d ? cov(a, b) / d : 0;
};
const quantile = (xs, q) => {
  if (!xs.length) return null;
  const s = xs.slice().sort((a, b) => a - b);
  const pos = (s.length - 1) * q;
  const lo = Math.floor(pos);
  const hi = Math.ceil(pos);
  return s[lo] + (s[hi] - s[lo]) * (pos - lo);
};
const day = (ms) => new Date(ms).toISOString().slice(0, 10);

// --- Parse price histories into { date -> close } in local units -----------------------------
const MINOR = { ZAC: ['ZAR', 100], GBP_P: ['GBP', 100], GBX: ['GBP', 100], ILA: ['ILS', 100] };
const series = {};
plan.forEach((p, i) => {
  const raw = parse(responses[i] ? (responses[i].data !== undefined ? responses[i].data : responses[i]) : null);
  const closes = {};
  let currency = 'USD';
  let factor = 1;
  if (p.provider === 'binance' && Array.isArray(raw)) {
    for (const k of raw) closes[day(Number(k[0]))] = Number(k[4]);
  } else if (p.provider === 'yahoo' && raw && raw.chart && raw.chart.result && raw.chart.result[0]) {
    const r = raw.chart.result[0];
    const q = r.indicators.quote[0];
    (r.timestamp || []).forEach((t, j) => {
      if (q.close[j] !== null && q.close[j] !== undefined) closes[day(t * 1000)] = q.close[j];
    });
    let cur = String((r.meta && r.meta.currency) || 'USD');
    if (cur === 'GBp') cur = 'GBP_P';
    cur = cur.toUpperCase();
    if (MINOR[cur]) {
      factor = 1 / MINOR[cur][1];
      currency = MINOR[cur][0];
    } else {
      currency = cur;
    }
  }
  const dates = Object.keys(closes).sort();
  series[p.key] = { ...p, closes, dates, currency, factor, ok: dates.length > 0, last: dates.length ? closes[dates[dates.length - 1]] * factor : null };
});

const fxRate = (ccy) => {
  if (!ccy || ccy === 'USD' || ccy === 'USDT' || ccy === 'USDC') return 1;
  const s = series['FX:' + ccy];
  return s && s.ok ? s.last : null;
};

