  const sym = String(h.symbol).toUpperCase();
  const qty = Number(h.quantity);
  if (h.asset_class === 'cash') {
    cash += qty;
    continue;
  }
  const isCrypto = h.asset_class === 'crypto' || h.asset_class === 'crypto_perp' || crypto.has(sym);
  let key = null;
  let priceUsd = null;
  let priceSource = null;
  if (isCrypto) {
    key = 'CRYPTO:' + sym;
    const s = series[key];
    if (h.asset_class === 'crypto_perp' && hl[sym] && hl[sym].mark > 0) {
      priceUsd = hl[sym].mark;
      priceSource = 'Hyperliquid mark';
    } else if (s && s.ok) {
      priceUsd = s.last;
      priceSource = 'Binance';
    } else if (hl[sym] && hl[sym].mark > 0) {
      priceUsd = hl[sym].mark;
      priceSource = 'Hyperliquid mark';
    }
  } else {
    const p = plan.find((x) => x.role === 'asset' && x.symbol === sym && x.provider === 'yahoo');
    key = p ? p.key : null;
    const s = key ? series[key] : null;
    if (s && s.ok) {
      const fx = fxRate(s.currency);
      if (fx) {
        priceUsd = s.last * fx;
        priceSource = 'Yahoo Finance (' + s.currency + ')';
      }
    }
  }
  if (priceUsd === null) {
    missing.push(sym);
    continue;
  }
  const exposure = qty * priceUsd;
  const pos = {
    symbol: sym,
    source: h.source,
    asset_class: h.asset_class,
    quantity: qty,
    price_usd: round(priceUsd, 6),
    price_source: priceSource,
    exposure_usd: round(exposure),
    series_key: key,
  };
  if (h.avg_cost != null) {
    const fxCost = isCrypto ? 1 : (fxRate(h.currency) || 1);
    pos.unrealized_pnl_pct = round(((priceUsd / (Number(h.avg_cost) * fxCost)) - 1) * 100 * Math.sign(qty));
  }
  if (h.asset_class === 'crypto_perp') {
    pos.side = qty < 0 ? 'short' : 'long';
    pos.entry = Number(h.avg_cost);
    pos.leverage = h.leverage;
    pos.unrealized_pnl_usd = round((priceUsd - Number(h.avg_cost)) * qty);
    if (h.liquidation_price) pos.liquidation_distance_pct = round((Math.abs(priceUsd - Number(h.liquidation_price)) / priceUsd) * 100);
    if (hl[sym] && isFinite(hl[sym].funding)) {
      pos.funding_apr_pct = round(hl[sym].funding * 24 * 365 * 100);
      pos.funding_paid_per_day_usd = round(exposure * hl[sym].funding * 24);
    }
  }
  positions.push(pos);
}

const spotValue = positions.filter((p) => p.asset_class !== 'crypto_perp').reduce((s, p) => s + p.exposure_usd, 0);
const equity = spotValue + cash;
const gross = positions.reduce((s, p) => s + Math.abs(p.exposure_usd), 0);
const net = positions.reduce((s, p) => s + p.exposure_usd, 0);
for (const p of positions) p.weight_pct = round(gross ? (Math.abs(p.exposure_usd) / gross) * 100 : 0, 1);
positions.sort((a, b) => b.weight_pct - a.weight_pct);

const classWeights = {};
for (const p of positions) classWeights[p.asset_class] = round((classWeights[p.asset_class] || 0) + p.weight_pct, 1);
const hhi = positions.reduce((s, p) => s + Math.pow(p.weight_pct / 100, 2), 0);

// --- Historical simulation on SPY trading days ----------------------------------------------
const bench = series['BENCH:SPY'];
const dates = bench && bench.ok ? bench.dates.slice(-121) : [];
const aligned = (key, toUsd) => {
  const s = series[key];
  if (!s || !s.ok) return null;
  const out = [];
  let last = null;
  let si = 0;
  for (const d of dates) {
    while (si < s.dates.length && s.dates[si] <= d) {
      last = s.closes[s.dates[si]] * s.factor;
      si++;
    }
    out.push(last === null ? null : last * (toUsd ? (fxRate(s.currency) || 1) : 1));
  }
  return out;
};
const returnsOf = (closes) => {
  const r = [];
  for (let i = 1; i < closes.length; i++) {
    r.push(closes[i] !== null && closes[i - 1] ? closes[i] / closes[i - 1] - 1 : 0);
  }
  return r;
};
const spyR = dates.length > 20 ? returnsOf(aligned('BENCH:SPY', false)) : [];
const assetR = {};
for (const p of positions) {
  if (!p.series_key || assetR[p.symbol]) continue;
  const closes = aligned(p.series_key, true);
  if (closes && closes.filter((x) => x !== null).length > 20) assetR[p.symbol] = returnsOf(closes);
}

let risk = null;
if (spyR.length > 20 && equity > 0) {
  const pnl = spyR.map((_, t) => positions.reduce((s, p) => s + (assetR[p.symbol] ? p.exposure_usd * assetR[p.symbol][t] : 0), 0));
  const pnlPct = pnl.map((x) => x / equity);
  const varPnl = sd(pnl) ** 2;
  let cum = 0;
  let peak = 0;
  let maxDd = 0;
  for (const x of pnl) {
    cum += x;
    peak = Math.max(peak, cum);
    maxDd = Math.max(maxDd, peak - cum);
  }
  const tail = pnl.filter((x) => x <= quantile(pnl, 0.05));
  risk = {
    window_days: pnl.length,
    method: 'historical simulation of current positions on the last ~6 months of daily returns (assets without history excluded)',
    var95_1d_usd: round(-quantile(pnl, 0.05)),
    var95_1d_pct_equity: round(-quantile(pnlPct, 0.05) * 100),
    cvar95_1d_usd: round(-mean(tail)),
    annualized_vol_pct_equity: round(sd(pnlPct) * Math.sqrt(252) * 100),
    beta_to_spy: round(cov(pnlPct, spyR) / (sd(spyR) ** 2 || 1)),
    hypothetical_sharpe: round(sd(pnlPct) ? (mean(pnlPct) / sd(pnlPct)) * Math.sqrt(252) : null),
    max_drawdown_pct_equity: round((maxDd / equity) * 100),
  };
  for (const p of positions) {
    const r = assetR[p.symbol];
    if (!r) continue;
    p.vol_annual_pct = round(sd(r) * Math.sqrt(252) * 100, 1);
    p.beta_to_spy = round(cov(r, spyR) / (sd(spyR) ** 2 || 1));
    p.risk_contribution_pct = round(varPnl ? ((p.exposure_usd * cov(r, pnl)) / varPnl) * 100 : null, 1);
  }
  const syms = Object.keys(assetR);
  const pairs = [];
  for (let i = 0; i < syms.length; i++) {
    for (let j = i + 1; j < syms.length; j++) {
      const c = corr(assetR[syms[i]], assetR[syms[j]]);
      if (Math.abs(c) >= 0.6) pairs.push(syms[i] + '/' + syms[j] + ' ' + round(c));
    }
  }
  risk.highly_correlated_pairs = pairs.slice(0, 8);
}

// --- Trade statistics (Invo/Hyperliquid fills and imported trades) -------------------------
const trades = $('Load Recent Trades').all().map((i) => i.json).filter((t) => t && t.symbol);
let tradeStats = null;
if (trades.length) {
  const closes = trades.filter((t) => t.realized_pnl !== null && Number(t.realized_pnl) !== 0);
  const wins = closes.filter((t) => Number(t.realized_pnl) > 0).map((t) => Number(t.realized_pnl));
  const losses = closes.filter((t) => Number(t.realized_pnl) < 0).map((t) => Number(t.realized_pnl));
  const sum = (xs) => xs.reduce((s, x) => s + x, 0);
  let streak = 0;
  for (const t of closes) {
    if (Number(t.realized_pnl) < 0) streak++;
    else break;
  }
  const counts = {};
  for (const t of trades) counts[t.symbol] = (counts[t.symbol] || 0) + 1;
  const since30 = Date.now() - 30 * 864e5;
  tradeStats = {
    fills_loaded: trades.length,
    first_fill: String(trades[trades.length - 1].executed_at).slice(0, 10),
    last_fill: String(trades[0].executed_at).slice(0, 10),
    fills_last_30d: trades.filter((t) => Date.parse(t.executed_at) >= since30).length,
    closing_fills: closes.length,
    win_rate_pct: round(closes.length ? (wins.length / closes.length) * 100 : null, 1),
    avg_win_usd: round(wins.length ? mean(wins) : null),
    avg_loss_usd: round(losses.length ? mean(losses) : null),
    payoff_ratio: round(wins.length && losses.length ? mean(wins) / Math.abs(mean(losses)) : null),
    profit_factor: round(losses.length ? sum(wins) / Math.abs(sum(losses)) : null),
    realized_pnl_usd: round(sum(closes.map((t) => Number(t.realized_pnl)))),
    fees_usd: round(sum(trades.map((t) => Number(t.fee || 0)))),
    largest_win_usd: round(wins.length ? Math.max(...wins) : null),
    largest_loss_usd: round(losses.length ? Math.min(...losses) : null),
    current_losing_streak: streak,
    most_traded: Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 5).map((e) => e[0] + ' x' + e[1]),
  };
}

const metrics = {
  as_of_utc: new Date().toISOString().slice(0, 16).replace('T', ' '),
  equity_usd: round(equity),
  cash_usd: round(cash),
  gross_exposure_usd: round(gross),
  net_exposure_usd: round(net),
  gross_leverage_x: round(equity ? gross / equity : null),
  asset_class_weights_pct: classWeights,
  largest_position: positions[0] ? positions[0].symbol + ' ' + positions[0].weight_pct + '%' : null,
  herfindahl_index: round(hhi, 3),
  effective_number_of_bets: round(hhi ? 1 / hhi : null, 1),
  risk,
  unpriced_holdings: missing,
};

// --- Deterministic text report (/risk) and the prompt for the investor panel (/analyze) ---------
const f = (v, suffix) => (v === null || v === undefined ? 'n/a' : Number(v).toLocaleString('en-US', { maximumFractionDigits: 2 }) + (suffix || ''));
const lines = [];
lines.push('📐 RISK REPORT (' + metrics.as_of_utc + ' UTC)');
lines.push('Equity ' + f(metrics.equity_usd, ' USD') + ' | gross exposure ' + f(metrics.gross_exposure_usd, ' USD') + ' | leverage ' + f(metrics.gross_leverage_x, 'x'));
lines.push('Net exposure ' + f(metrics.net_exposure_usd, ' USD') + ' | cash/USDC ' + f(metrics.cash_usd, ' USD'));
lines.push('Concentration: largest ' + (metrics.largest_position || 'n/a') + ', HHI ' + f(metrics.herfindahl_index) + ' (≈' + f(metrics.effective_number_of_bets) + ' independent bets)');
lines.push('Asset classes: ' + (Object.entries(classWeights).map((e) => e[0] + ' ' + e[1] + '%').join(', ') || 'n/a'));
if (risk) {
  lines.push('');
  lines.push('1-day VaR 95%: ' + f(risk.var95_1d_usd, ' USD') + ' (' + f(risk.var95_1d_pct_equity, '%') + ' of equity), CVaR ' + f(risk.cvar95_1d_usd, ' USD'));
  lines.push('Volatility ' + f(risk.annualized_vol_pct_equity, '%') + ' p.a. | beta to S&P 500 ' + f(risk.beta_to_spy) + ' | max drawdown (6m sim) ' + f(risk.max_drawdown_pct_equity, '%'));
  if (risk.highly_correlated_pairs.length) lines.push('Highly correlated: ' + risk.highly_correlated_pairs.join(', '));
}
lines.push('');
lines.push('Positions (weight of gross exposure):');
for (const p of positions.slice(0, 15)) {
  let l = '• ' + p.symbol + (p.side ? ' ' + p.side.toUpperCase() : '') + ' ' + p.weight_pct + '% (' + f(p.exposure_usd, ' USD') + ')';
  if (p.risk_contribution_pct !== undefined && p.risk_contribution_pct !== null) l += ', risk ' + p.risk_contribution_pct + '%';
  if (p.vol_annual_pct) l += ', vol ' + p.vol_annual_pct + '%';
  if (p.liquidation_distance_pct !== undefined) l += ', liq ' + p.liquidation_distance_pct + '% away';
  if (p.funding_apr_pct !== undefined) l += ', funding ' + p.funding_apr_pct + '% APR';
  lines.push(l);
}
const warnings = [];
for (const p of positions) {
  if (p.weight_pct > 20) warnings.push(p.symbol + ' is ' + p.weight_pct + '% of exposure (limit 20%)');
  if (p.liquidation_distance_pct !== undefined && p.liquidation_distance_pct < 15) warnings.push(p.symbol + ' is only ' + p.liquidation_distance_pct + '% from liquidation');
}
for (const [k, v] of Object.entries(classWeights)) if (v > 60) warnings.push(k + ' is ' + v + '% of exposure (limit 60%)');
if (metrics.gross_leverage_x > 2) warnings.push('gross leverage ' + metrics.gross_leverage_x + 'x');
if (missing.length) warnings.push('no price for: ' + missing.join(', '));
if (warnings.length) {
  lines.push('');
  lines.push('⚠️ ' + warnings.join('\n⚠️ '));
}
if (tradeStats) {
  lines.push('');
  lines.push('Trading record (' + tradeStats.fills_loaded + ' fills, ' + tradeStats.first_fill + ' → ' + tradeStats.last_fill + '):');
  lines.push('Win rate ' + f(tradeStats.win_rate_pct, '%') + ', payoff ' + f(tradeStats.payoff_ratio) + ', profit factor ' + f(tradeStats.profit_factor)
    + ', realized ' + f(tradeStats.realized_pnl_usd, ' USD') + ', fees ' + f(tradeStats.fees_usd, ' USD'));
}
const riskText = positions.length || cash
  ? lines.join('\n')
  : '📐 No holdings to measure yet. Add some with /portfolio, a CSV import, or /wallet + /sync.';

const summary = '📊 Equity ' + f(metrics.equity_usd, ' USD') + ' | leverage ' + f(metrics.gross_leverage_x, 'x')
  + (risk ? ' | VaR95 ' + f(risk.var95_1d_pct_equity, '%') + ' | vol ' + f(risk.annualized_vol_pct_equity, '%') : '')
  + '\nTop: ' + positions.slice(0, 5).map((p) => p.symbol + ' ' + p.weight_pct + '%').join(', ')
  + (warnings.length ? '\n⚠️ ' + warnings.slice(0, 3).join('; ') : '');

const prompt = 'Review this portfolio.\n\nPORTFOLIO METRICS (JSON, computed from live prices):\n' + JSON.stringify(metrics, null, 1)
  + '\n\nPOSITIONS:\n' + JSON.stringify(positions.map((p) => { const c = { ...p }; delete c.series_key; return c; }), null, 1)
  + '\n\nTRADE HISTORY STATS:\n' + (tradeStats ? JSON.stringify(tradeStats, null, 1) : 'no trades stored')
  + '\n\nRISK FLAGS:\n' + (warnings.join('\n') || 'none');

return [{
  json: {
    chat_id: ctx.chat_id,
    route: ctx.route,
    mode: 'analyze',
    symbol: null,
    request: ctx.route === 'risk' ? '/risk' : '/analyze',
    reply: riskText,
    summary,
    user_prompt: prompt,
    has_holdings: positions.length > 0 || cash > 0,
  },
}];

// Build the LangChain server request from the skill framework stored in Supabase (agent_skills).
// /analyze fans out into one item per investor persona. The shared system prompt and data come
// first and the persona lens last, so Ollama can reuse the cached prompt prefix across personas.
const ctx = $('Build Context').first().json;
const input = $input.first();
const skills = ctx.skills || {};
const mode = ctx.route === 'risk' ? 'analyze' : ctx.route;

const FALLBACK_CORE = 'You are a careful market analyst. Use only the data provided and never invent prices, levels or news. '
  + 'Give a bias, the key signals, one action (Buy/Add/Hold/Trim/Sell/Hedge/Wait) with an invalidation level, and the main risks. '
  + 'Plain text, under 1,200 characters. Not financial advice.';
const compose = (parts) => parts.filter(Boolean).join('\n\n----\n\n')
  + '\n\nCurrent UTC date: ' + new Date().toISOString().slice(0, 10) + '.';

const holdingsText = (ctx.holdings || []).length
  ? ctx.holdings.map((h) => h.symbol + ' ' + h.asset_class + ' qty ' + h.quantity + (h.avg_cost != null ? ' @ ' + h.avg_cost + ' ' + h.currency : '') + ' [' + h.source + ']').join('\n')
  : 'none stored';

const base = { chat_id: ctx.chat_id, telegram_id: ctx.telegram_id, mode, persona: null, image_b64: null, image_mime: null };

if (mode === 'analyze') {
  const PERSONAS = [
    { slug: 'persona_buffett', name: 'Warren Buffett' },
    { slug: 'persona_dalio', name: 'Ray Dalio' },
    { slug: 'persona_wood', name: 'Cathie Wood' },
    { slug: 'persona_ackman', name: 'Bill Ackman' },
  ];
  const available = PERSONAS.filter((p) => skills[p.slug]);
  const panel = available.length ? available : [{ slug: null, name: 'Analyst' }];
  const system = compose([skills.core || FALLBACK_CORE, skills.portfolio, skills.house_rules]);
  return panel.map((p) => ({
    json: {
      ...base,
      persona: p.name,
      symbol: null,
      request: '/analyze [' + p.name + ']',
      system_prompt: system,
      user_prompt: input.json.user_prompt + (p.slug ? '\n\n====\n\nYOUR ROLE FOR THIS ANSWER:\n' + skills[p.slug] : ''),
    },
  }));
}

let userPrompt;
let request;
let imageB64 = null;
let imageMime = null;
if (mode === 'chart') {
  request = ctx.text || '(chart without caption)';
  userPrompt = 'The user uploaded a chart screenshot.'
    + (ctx.text ? ' Caption: "' + ctx.text + '".' : ' No caption was given.')
    + ' Run the CHART SNAPSHOT checklist on the attached image.\n\nUSER HOLDINGS:\n' + holdingsText;
  const bin = input.binary && input.binary.data;
  if (bin) {
    const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
    imageB64 = buffer.toString('base64');
    imageMime = bin.mimeType && bin.mimeType.startsWith('image/') ? bin.mimeType : 'image/jpeg';
  }
} else if (mode === 'ask') {
  request = ctx.text;
  userPrompt = 'User message: ' + ctx.text + '\n\nUSER HOLDINGS:\n' + holdingsText
    + '\n\nNo live market data was fetched for this message. For general or educational questions answer directly in under 1,000 characters and skip the BIAS/ACTION template. '
    + 'If the question needs live prices or news, answer conceptually and suggest /market SYMBOL, /news or sending a chart screenshot.';
} else {
  request = input.json.request;
  userPrompt = input.json.user_prompt;
}

const SKILL_FOR_MODE = { chart: 'chart', market: 'market', news: 'news', ask: null };
return [{
  json: {
    ...base,
    symbol: input.json.symbol || null,
    request,
    system_prompt: compose([skills.core || FALLBACK_CORE, SKILL_FOR_MODE[mode] ? skills[SKILL_FOR_MODE[mode]] : '', skills.house_rules]),
    user_prompt: userPrompt,
    image_b64: imageB64,
    image_mime: imageMime,
  },
}];

// Collect the LangChain server answer(s) into one Telegram reply. For /analyze this is the investor panel.
const prepared = $('Prepare Agent Input').all().map((i) => i.json);
const outputs = $input.all().map((i) => i.json);
const first = prepared[0] || {};

const textOf = (o) => {
  if (o && typeof o.output === 'string' && o.output.trim()) return o.output.trim();
  let err = 'no response';
  if (o && o.error) err = o.error.message || JSON.stringify(o.error);
  else if (o && o.detail) err = typeof o.detail === 'string' ? o.detail : JSON.stringify(o.detail);
  return '⚠️ The LangChain server did not answer (' + String(err).slice(0, 200) + '). '
    + 'Check that the local AI is running (on that server: curl http://127.0.0.1:8000/health), the URL on the "Ask LangChain Analyst" node, and the API key credential.';
};

let reply;
if (first.mode === 'analyze') {
  const ICONS = { 'Warren Buffett': '👔', 'Ray Dalio': '🌊', 'Cathie Wood': '🚀', 'Bill Ackman': '🎯' };
  const verdicts = [];
  const sections = prepared.map((p, i) => {
    const text = textOf(outputs[i]);
    const v = text.match(/VERDICT:\s*([A-Za-z ]{3,20})/i);
    if (v) verdicts.push(p.persona.split(' ').pop() + ': ' + v[1].trim());
    return '━━━━━━━━━━━━━━\n' + (ICONS[p.persona] || '•') + ' ' + p.persona.toUpperCase() + '\n\n' + text;
  });
  let header = '🏛️ INVESTOR PANEL\n';
  try {
    header += $('Compute Portfolio Metrics').first().json.summary + '\n';
  } catch (e) {
    // metrics unavailable; panel still useful
  }
  reply = header + '\n' + sections.join('\n\n')
    + (verdicts.length ? '\n\n━━━━━━━━━━━━━━\n🧮 Panel verdicts: ' + verdicts.join(' · ') : '')
    + '\n\n/risk for the full risk report. Not financial advice.';
} else {
  const TITLES = { chart: '📈 CHART READ', market: '🌍 MARKET OVERVIEW', news: '📰 NEWS SCAN', ask: '💬 ANALYST' };
  reply = (TITLES[first.mode] || '') + (first.symbol ? ' ' + first.symbol : '') + '\n\n' + textOf(outputs[0]);
}

return [{ json: { chat_id: first.chat_id, reply } }];

// Telegram caps messages at 4096 characters and the send node parses HTML, so split on line breaks
// and escape &, < and >.
const LIMIT = 3600;
const escape = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const out = [];
for (const item of $input.all()) {
  const chatId = item.json.chat_id;
  let text = String(item.json.reply === undefined || item.json.reply === null ? '' : item.json.reply).trim() || '(empty response)';
  text = text.replace(/\*\*(.+?)\*\*/g, '$1').replace(/^#{1,6}\s*/gm, '');
  const chunks = [];
  while (text.length > LIMIT) {
    let cut = text.lastIndexOf('\n', LIMIT);
    if (cut < LIMIT / 2) cut = LIMIT;
    chunks.push(text.slice(0, cut));
    text = text.slice(cut).replace(/^\s+/, '');
  }
  chunks.push(text);
  chunks.forEach((c, i) => {
    out.push({ json: { chat_id: chatId, text: escape(c) + (chunks.length > 1 ? '\n(' + (i + 1) + '/' + chunks.length + ')' : '') } });
  });
}
return out;
